; play the footstep sample
; a footstep is basically a click.  Just play any sample for a short time 
; and you'll get a nice click sound.  Just the act of shutting down the SB
; makes a little pop noise.
footstep proc
       	cmp	word ptr cs:[sbbase], -1
       	jz	speakerFootstep

	cmp	cs:[alarmSounding], -1		; no footsteps during alarm
	jz	noFS				; jl added


	push	ax
	push	bx
	push	cx
	push	dx
   	mov	dx, cs:[sbBase]
   					; play just a few samples
	mov	ax, cs:[sampleSeg]		; of anything to make a click
	lea	bx, soundBlasterSeg:heil	; load offset
	add	bx, cs:[clickSound]			
	mov	cx, 46				; load # of samples
	call	playSample
	pop	dx
	pop	cx
	pop	bx
	pop	ax
	ret

speakerFootstep:
       	call    speaker_short
noFS:
       	ret
footstep endp




