						;  get keybd char in al, ah=scan
		cmp	al, ESCAPE		; 1Bh
		jne	loc_65			; Jump if not equal
		jmp	loc_411

		;
		; get the next key from the demo key sequencer
		;
loc_65::


            	mov     word ptr cs:[ctrlKey],0
		push	es
		;call    esto900h		; changed to data segment
                mov	si, dataSeg
		mov	es, si

		mov     si, cs:[demoKeyPtr]           ;data_133
                mov     bx, word ptr cs:[v4EE]  ; end of demo flag?
		cmp	bx, es:[si]
		jne	loc_69			; Jump if not equal
		add	si,2
		mov	al, es:[si]
		inc	si			; next key for next time
loc_66::
