		cmp	al, 40h			; '@'
		jb	loc_68			; Jump if below
		add	al, 20h			; ' '
loc_68::
                call    checkKey
loc_69::
		pop	es
		retn


loc_70::
        
                mov     word ptr cs:[ctrlKey],0
                call    joystickInit            ;sub_17


