checkKey        proc    near
		mov	bx, 27h			; data_335e

loc_73::
                cmp     al,byte ptr cs:[bx+allowedKeys]    ;data_137+8[bx] ; ('P')
		je	loc_74			; Jump if equal
		dec	bx
		jns	loc_73			; Jump if not sign
		retn

loc_74::

		cmp	bx,11h			; Escape key or higher
		jae	loc_76			; Jump if above or =

                mov     cl,byte ptr cs:[bx+directions] ;83Bh][bx]       ; 
		or	cl,cl			; Zero ?
		jns	loc_75			; Jump if not sign
		and	cl, NOT BIT7 		; 7Fh
                mov     byte ptr cs:[gunDir],cl   ; store gun value
		retn
loc_75::
                mov     byte ptr cs:[moveDir],cl   ; store move value
		retn
loc_76::
                mov     word ptr cs:[ctrlKey],bx
		retn
checkKey        endp

