		or	al, al			; Zero ?
		pop	es
		pop	si
		retn

loc_77::

	;
	; non demo mode "random" values.  Reads a byte from BIOS segment!
	; values are not time based, yet the seed is generated while waiting
	; in the main menu for the user to select a game.  Cool idea.
	;

		push	si
		push	ds
                mov     si, cs:[seed]                   ;data_430e (seed)
		mov	ax, 0F800h			
		mov	ds, ax				
                mov     ax, ds:[si]
		pop	ds
badValue:                
		add     word ptr cs:[seed], 1567        ; 61Fh
		; BUGFIX!
		cmp	word ptr cs:[seed], -1		; reading a word from
		jz	badValue			; FFFF will GPF! 
		; end 
		or	al,al				; Zero ?
		pop	si
		retn
getRand         endp

