; draws the available passes on left side of screen
printPasses     proc    near
		mov	di, 0c80h		; starting row prolly
                mov     al, cs:[passes]           ; data_382e
		
		mov     byte ptr cs:[passRow], 14h      ;data_437e,14h
loc_135::
		shr	al, 1			; Shift w/zeros fill
		mov	bx, 2020h
		push	ax
		jnc	loc_136			; Jump if carry=0
                mov     bl, cs:[passRow]                ;data_437e
		mov	bh, 13h
loc_136::
		push	bx
		mov	al, bl
		xor	dx, dx			; Zero register
                call    draw2Screen            ; 1st draws [1]
		pop	bx
		mov	al, bh
                call    draw2Screen
		add	di, 280h		;640 (2 rows down)
		pop	ax
                inc     byte ptr cs:[passRow]   ;data_437e
                cmp     byte ptr cs:[passRow], 19h      ;data_437e,19h
		jne	loc_135			; Jump if not equal
		retn
printPasses     endp


