;��������������������������������������������������������������������������
;                              SUBROUTINE
;��������������������������������������������������������������������������
; input: al=sprite to draw?
;        di, dx=position something
draw2Screen          proc    near
;loc_147::
		push	si
		cmp	al, 0Dh
		je	loc_150			; Jump if equal
		
		push	di
		add	di,dx
		xor	ah,ah			; Zero register
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill

                cmp     byte ptr cs:[monitorType],1     ;data_9e,1
		je	loc_148			; Jump if equal
		
		cmp	ax, 1B0h		; erase graphic?
		je	loc_148			; Jump if equal
		
		add	ax, offset cs:v11A4    	; this is dumb code
		jmp	short loc_149
loc_148::
		add	ax, offset cs:v11A4  
loc_149::
		sub	ax,0E0h
		mov	si,ax
		movsw				; Mov [si] to es:[di]
		add	di, 1ffeh		; data_560e
		movsw				; Mov [si] to es:[di]
		sub	di, 1FB2h		; 1ffe/1fb2 interlaced CGA
		movsw				; Mov [si] to es:[di]
		add	di, 1ffeh		; data_560e
		movsw				; Mov [si] to es:[di]
		sub	di, 1FB2h
		movsw				; Mov [si] to es:[di]
		add	di, 1ffeh		; data_560e
		movsw				; Mov [si] to es:[di]
		sub	di, 1FB2h
		movsw				; Mov [si] to es:[di]
		add	di, 1ffeh		; data_560e
		movsw				; Mov [si] to es:[di]
		pop	di
		add	dx, 2
		cmp	dx, 50h
		jne	loc_151			; Jump if not equal
loc_150::
                mov     dx, word ptr cs:[xpos]
		add	di, 320			; next line 140h
loc_151::
		pop	si
		clc				; Clear carry flag
		retn
draw2Screen    endp


