;��������������������������������������������������������������������������
;                              SUBROUTINE
;��������������������������������������������������������������������������
;input: bl=8bit value BCD?
;outpt: dx=decoded value
decodeBCD	proc	near		;sub_44		proc	near
		mov	dl,bl
		and	dl,7		; dl=bits2:0
		mov	dh,bl		; dh=6:4
		shr	dh,1			; Shift w/zeros fill
		shr	dh,1			; Shift w/zeros fill
		shr	dh,1			; Shift w/zeros fill
		retn
decodeBCD  	endp


;��������������������������������������������������������������������������
;                              SUBROUTINE
;��������������������������������������������������������������������������
; input bx=desired position?
; output dx, dx= x,y coords?

getScreenPos          proc    near
		call	decodeBCD		;sub_44
		shl	dl,1			; Shift w/zeros fill
		shl	dl,1			; Shift w/zeros fill
		add	dl,5
		shl	dh,1			; Shift w/zeros fill
		add	dh,2
		mov	al,dh
		xor	ah,ah			; Zero register
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill
		shl	ax,1			; Shift w/zeros fill
		add	ah,dh
		mov	di,ax
		xor	dh,dh			; Zero register
		shl	dx,1			; Shift w/zeros fill
                mov     cs:[xpos], dx           ;data_441e,dx
                mov     word ptr cs:[ypos],di
		retn
getScreenPos          endp



