; play a click sound to represent the tumbler going into the lock.
playClick proc
	cmp	cs:[sbBase], -1
	jz	speakerCLick
	
	push	ax
	push	bx
	push	cx
	push	dx
	
	mov	dx, cs:[sbBase]
						; play just a few samples
	mov	ax, cs:[sampleSeg]		; of anything to make a click
	lea	bx, soundBlasterSeg:heil	; load offset
	add	bx, 400
	mov	cx, 46				; load # of samples
	call	playSample

		
	pop	dx
	pop	cx
	pop	bx
	pop	ax
	ret




speakerClick:
	call	do_speaker
	ret
playClick endp




