; restore original game sectors
restoreSectors900 proc
	push	cx
	push	si
	push	ds
	call	esto900h
	mov	di, 4
	mov	si, cs:[bufSeg900]
	mov	ds, si
	xor	si, si
	mov	cx, 8 * 4 * 512
	rep	movsb
	pop	ds
	pop	si
	pop	cx
	ret
restoreSectors900 endp

; restore original game sectors
restoreSectorsD00 proc
	push	cx
	push	si
	push	ds
	push	es
	
	call	setDSto0D00
	push	ds
	pop	es

	mov	di, 0
	mov	si, cs:[bufSegD00]
	mov	ds, si
	xor	si, si
	mov	cx, 8 * 3 * 512
	rep	movsb
	pop	es
	pop	ds
	pop	si
	pop	cx
	ret
restoreSectorsD00 endp



; make a copy of 8 sectors from original game to scratchpad
copySectors900 proc
	push	ax
	push	es
	push	ds
	push	di
	push	si
	push	cx
	call	esto900h
	push	es
	pop	ds
	mov	di, cs:[bufseg900]
	mov	es, di
	xor	di, di
	mov	si, 4
	mov	cx, 8 * 4 * 512
	rep	movsb
	pop	cx
	pop	si
	pop	di
	pop	ds
	pop	es
	pop	ax
	ret
copySectors900 endp


; make a copy of 8 sectors from original game to scratchpad
copySectorsD00 proc
	push	ax
	push	es
	push	ds
	push	di
	push	si
	push	cx
	call	setDSto0D00
	mov	di, cs:[bufsegD00]
	mov	es, di
	xor	di, di
	mov	si, 0
	mov	cx, 8 * 3 * 512
	rep	movsb
	pop	cx
	pop	si
	pop	di
	pop	ds
	pop	es
	pop	ax
	ret
copySectorsD00 endp








