;
; play a voice sample over the speaker
;

loc_625::
		cmp	cs:[sbBase], -1
		jz	speakerOnly
;
; soundblaster patch - DI= voice patch # to play
;
		
		push	bx
		push	dx
		mov	dx, cs:[sbBase]
 		
		mov	ax, cs:[sampleSeg] 		; needed a 2nd 64k

		cmp	di, 0
		jnz	noShift

		;
		; if sample to play is 0, it's a death scream.
		; to add some fun to the game, randomly change the pitch
		;
		call	changePitch
		
noShift:		
		cmp	di, 4			 	; segment for all data
		jbe	gotSeg
		add	ax, 1000h
gotSeg:		
		shl	di, 1				; make word value
		mov	bx, cs:[sbVoiceTable+di]	; load offset
		mov	cx, cs:[sbVoiceTableSize+di]	; load # of samples


		call	playSample
		mov	cs:[samplePlaying], -1		; set wait flag
		mov	cs:[pitch], DEFAULT_PITCH	; restore pitch
		mov	cx, 4000			; timeout
wait4Sample:
		cmp	cs:[samplePlaying], -1		; hang until sample
		jnz	sampleFinished			; is finished.
		call	starttime
		call	delaytime
		loop	wait4Sample

sampleFinished:
		mov	cs:[samplePlaying], 0		; cleanup in case no IRQ
		pop	bx
		pop	dx
		jmp	loc_631

; randomly change the pitch of the death scream
changePitch proc
		push	ax
		call	getRand
		test	al, 10h				; pos or neg?
		pushf
		and	al, 0fh				; max range
		add	cs:[pitch], al
		popf
		jz	exitCP
		sub	cs:[pitch], al
		sub	cs:[pitch], al
exitCP:
		pop	ax
		ret
changePitch endp




