fireGunSound	proc	near

		cmp	cs:[sbBase], -1
		jz	speakergun

		;
		; play a crash sound over the soundblaster.
		;

		push	ax
		push	bx
		push	cx
		push	dx
		mov	dx, cs:[sbBase]

		mov	ax, cs:[sampleSeg]	 ; needed a 2nd 64k
		add	ax, 1000h
		lea	bx, soundBlasterSeg2:gun  ; load offset
                mov     cx, 6980                ; load # of samples
	   	call	playSample

		
		pop	dx
		pop	cx
		pop	bx
		pop	ax
		ret





speakerGun:
		push	ax
		push	bx
		mov	al,1Fh
                call    speaker_low
		mov	al,1Fh
                call    speaker_high
		mov	al,3Fh			; '?'
                call    speaker_low
		mov	al,3Fh			; '?'
                call    speaker_high
		mov	al,7Fh
                call    speaker_low
		mov	al,7Fh
                call    speaker_high
		mov	al,7Fh
                call    speaker_high
                cmp     byte ptr cs:[cpuType], 0  ;data_546e,0
		jne	loc_647_2		; Jump if not equal
		mov	al,0FFh
                call    speaker_low
		mov	al,0FFh
                call    speaker_high
loc_647_2::
		mov	bl,0E0h
		mov	al,2
		call	sub_140
		pop	bx
		pop	ax
		retn
fireGunSound	endp


;��������������������������������������������������������������������������
;                              SUBROUTINE
;��������������������������������������������������������������������������
; trashes the screen temporarily whenever the player hits a wall
;
screenGarbage	proc	near

		push	ds
		mov	ax, 0F800h
		mov	ds, ax
		mov	cx, 1000h
		mov	di, 2000h		;data_566e

locloop_648::
                mov     ax, ds:[di]
		xor	es:[di], ax
		add	di, 2
		loop	locloop_648		; Loop if cx > 0

		pop	ds
		mov	al, 0FFh
		call	crashSound

		cmp	cs:[cpuType], 0
		jnz	skipDelay
		call	startTime		; slight delay to show effect
		call	delayTime
skipDelay:
	  ;jl	call	speaker_low		;jmp	loc_640
		ret
screenGarbage	endp


;��������������������������������������������������������������������������
;                              SUBROUTINE
;��������������������������������������������������������������������������
; input: si=?
; outpt: al=83-86h
sub_153		proc	near			;@4ad5
		mov	ax,si
		
		shr	al,1			; Shift w/zeros fill
		shr	al,1			; Shift w/zeros fill
		shr	al,1			; Shift w/zeros fill
		shr	al,1			; Shift w/zeros fill

		and	al,3			; force to 0-3
		add	al,3			; make 3-6
		or	al,80h			; make 83-86
;		jmp	loc_621		; routine is called now 
sub_153		endp

		db	0C3h

;��������������������������������������������������������������������������
;                              SUBROUTINE
;��������������������������������������������������������������������������
; 
speaker_toggle     proc    near
		push	ax
                cmp     byte ptr cs:[soundEnabled], FALSE	;v478C],0
		je	loc_649			; Jump if not equal
		in	al, 61h			; port 61h, 8255 port B, read
		and	al, NOT BIT0		;0FEh
		xor	al, 2			; speaker data enable
		out	61h,al			; port 61h, 8255 B - spkr, etc
loc_649::
		pop	ax
		retn
speaker_toggle     endp


;��������������������������������������������������������������������������
