speaker_delay         proc    near
;input AL delay amount? WTF is this all about?  looks like a weird delay.

loc_650::
		push	ax
loc_651::
		push	ax
		pop	ax
		sub	al,1
		jnz	loc_651			; Jump if not zero
		pop	ax
		sub	al,1
		jnz	loc_650			; Jump if not zero
		sti				; Enable interrupts
		retn
speaker_delay         endp



