; starttime - read the current time of day and save the current ms
; used in conjunction with delaytime to return only after 1ms has passed.
;
;

starttime proc
		; save the current time (millisec)
                push    ax
                push    cx
                push    dx
		pushf
                
		mov     ah, 2ch
                int     21h
                mov     cs:[ms], dl            ; save current ms

		popf
		pop     dx
                pop     cx
                pop     ax
		ret
starttime	endp




; delaytime - wait at least 1ms before exiting.		
delaytime proc		
		push    ax
                push    cx
                push    dx
		pushf
witforit:
                mov     ah, 2ch
                int     21h
                cmp     dl, cs:[ms]
                jz      witforit

		popf
                pop     dx
                pop     cx
                pop     ax
		ret


ms	db	0
delaytime endp


memalloc	proc
; input: AX = # of paragraphs required
; output: AX = segment of block to use
	push	bx
	mov	bx, ax
	mov	ah, 48h
	int	21h
	pop	bx
	ret
memalloc	endp



;-- SETFREE: Release memory not used  ----------------
;-- Input    : ES = address of PSP
;-- Output   : none
;-- Register : AX, BX, CL and FLAGS are changed 
;-- Info     : Since the stack-segment is always the last segment in an 
;              EXE-file, ES:0000 points to the beginning and SS:SP
;              to the end of the program in memory. Through this the
;              length of the program can be calculated 
; call this routine once at the beginning of the program to free up memory
; assigned to it by DOS.

setfree   proc near

          mov  bx,ss              ;first subtract the two segment addresses
          mov  ax,es              ;from each other. The result is
          sub  bx,ax              ;number of paragraphs from PSP
                                  ;to the beginning of the stack
          mov  ax,sp              ;since the stackpointer is at the end of
          mov  cl,4               ;the stack segment, its content indicates
          shr  ax,cl              ;the length of the stack
          add  bx,ax              ;add to current length
          inc  bx                 ;as precaution add another paragraph

          mov  ah,4ah             ;pass new length to DOS
          int  21h
          ret                     ;back to caller

setfree   endp

cpuDetect proc
; 8088/8086 test - Use rotate quirk - All later CPUs mask the CL
;   register with 0Fh, when shifting a byte by cl bits.  This 
;   test loads CL with a large value (20h) and shifts the AX
;   register right.  With the 8088, any bits in AX are shifted 
;   out, and becomes 0.  On all higher level processors, the
;   CL value of 20h is anded with 0Fh, before the shift.  This
;   means the effective number of shifts is 0, so AX is 
;   unaffected.

        mov     cl, 20h            ; load high CL value
        mov     ax, 1              ; load a non-zero value in AX
        shr     ax, cl             ; do the shift
        cmp     ax, 0              ; if zero, then 8088/86
        jne     up186              ; jump if not 8088/86

; V20/V30 test - It is now either a V20/V30 or a 8088.  I'll use
;   another undocumented trick to find out which.  On the 8088,
;   0Fh performs a POP CS.  On the V20/V30, it is the start of
;   a number of multi-byte instructions.  With the byte string
;   0Fh, 14h, C3h the CPU will perform the following:
;               8088/8086               V20/V30
;             pop     cs              set1   bl, cl  
;             adc     al, 0C3h

        xor     al, al             ; clear al and carry flag
        push    cs
        db      0Fh, 14h, 0C3h     ; instructions (see above)
        cmp     al, 0C3h           ; if al is C3h then 8088/8086
        jne     upV20
        mov     ax, 0              ; set 8088/8086 flag
        jmp     uP_Exit

upV20:
        pop     ax                 ; correct for lack of pop cs
        mov     ax, 200h           ; set V20/V30 flag
        jmp     uP_Exit

; 80186/80188 test - Check what is pushed onto the stack with a 
;   PUSH SP instruction.  The 80186 updates the stack pointer 
;   before the value of SP is pushed onto the stack.  With all
;   higher level processors, the current value of SP is pushed
;   onto the stack, and then the stack pointer is updated.
        
up186:  
        mov     bx, sp             ; save the current stack ptr
        push    sp                 ; do test
        pop     ax                 ; get the pushed value
        cmp     ax, bx             ; did SP change ?
        je      up286              ; if not, it's a 286+ 
        mov     ax, 1              ; set 80186 flag
        jmp     up_Exit

up286:
        mov     ax, 2

uP_Exit:
        ret


cpuDetect endp



; examine the DOS version, CPU type and memory size.
; exits to DOS from here if the machine is too wimpy.
checkRequirements proc

		mov	ax, 3001h
		int	21h
		cmp	al, 2
		jae	DOSok

		; eek! we're on a really old version of DOS!

		lea	dx, dosVerMsg
		mov	ah, 9
		int	21h			; hope this works on DOS 1.x!

		mov	ax, 4c02h		; this too!
		int	21h
		jmp	$			; just in case

nonMemMsg       db      "Error: Insufficient memory to play Beyond Castle Wolfenstein",10,13,"$"
dosVerMsg	db	"Error: Beyond Castle Wolfenstein requires at least DOS 2.0",10,13,"$"

DOSok:
		mov	ax, cs
		mov	ds, ax
                call    setfree                 ; deallocate unused DOS memory
                
		mov     ax, (8 * 4 * 512) / 16  ; 32 sectors in paragraphs
                call    memAlloc                ; reserve for game scratchpad
		jc	memError
                mov     cs:[bufseg900], ax      ; save our segment


		mov     ax, (8 * 3 * 512) / 16  ; 32 sectors in paragraphs
                call    memAlloc                ; reserve for game scratchpad
                mov     cs:[bufsegD00], ax      ; save our segment
		jnc	enoughMem


memError:
		; eek!  we've run out of memory!

		lea	dx, nonMemMsg
		mov	ah, 9
		int	21h
		jmp	exitProgram

enoughMem:

                sti                             ; Enable interrupts
		cld				; Clear direction

		
		call	cpuDetect		; see if it's an 8088 or less
                cmp     ax, 2
                jz      cpuOK
                mov     cs:[cpuType], 80h       ; set flag for OLD cpu!

cpuOK:
                call    underWindows?           ; in a DOS shell?
                jnc     exitCSR
                or      cs:[flags], IN_WIN      ; set flag 
exitCSR:
                ret
checkRequirements endp
flags	dw	0			; misc flags, settable via cmd line
NOSB	equ	BIT0			; no soundblaster flag
IN_WIN  equ     BIT1                    ; running under windows flag


; examine the supplied command line and set flags as appropriate.

checkCommandLine proc
 	push    es
        push    ds
        push    bx
        push    si
	push	ax

        push    ds
        pop     es

        mov     ah, 51h                         ; get PSP
        int     21h
        mov     ds, bx

        mov     si, 80h
        xor	bh, bh
	mov     bl, byte ptr[si]
        add     si, bx
        inc     si

        mov     byte ptr[si], NULL              ; zero terminate

        mov     si, 81h
 	
cmdlineloop:
        lodsb

        cmp     al, " "                 ; found a space?
        jz      cmdlineloop
	cmp	al, "-"
	jz	checkSwitch
	cmp	al, "/"
	jz	checkSwitch
	cmp	al, NULL
	jz	exitCmdLine
	cmp	al, CR
	jz	exitCmdLine
	jmp	cmdlineloop

checkSwitch:
	cmp	word ptr ds:[si], "on"
	jnz	nextcmd

	cmp	word ptr ds:[si+2], "bs"
	jnz	nextcmd

	or	cs:[flags], NOSB
	add	si, 4
	jmp	cmdlineLoop

nextcmd:

	cmp	word ptr ds:[si], "uq"
	jnz	cmdlineloop
	cmp	word ptr ds:[si+2],"ei"
	jnz	cmdlineLoop
	cmp	byte ptr ds:[si+4], "t"
	jnz	cmdlineloop

	mov	cs:[soundEnabled], FALSE
	add	si, 5
	jmp	cmdlineLoop
exitCmdline:
	pop	ax
	pop	si
	pop	bx
	pop	ds
	pop	es

	ret
checkCommandLine endp
; underWindows? - detect if we're running in a DOS box.
; input: none
; outpt: CY set if running under NT or windows 9x/ME
;
underWindows?   proc public
        call    NTDetect
        jc      exitUW

	push    ax
	push	bx
	push	cx
	mov     ax, 160ah
        int     2fh
        cmp     ax, 160ah               ; returns 0 if supported.
	pop	cx
	pop	bx
	pop	ax
	clc
        jz      exitUW
        stc
exitUW:
        ret
underWindows?   endp

; returns CY if under NT based O/S
NTDetect proc public
	push	ax
	push	bx
	push	dx
	mov	ax, 3306h
	int	21h
        cmp     bx, 3205h               ; NT signature
        clc
        jnz     notNT
        stc
notNT:
	pop	dx
	pop	bx
	pop	ax
	ret
NTDetect endp


;===========================================================================
; soundblaster support
;===========================================================================

sbBase	dw	-1			; storage for base address of SB.

; input: dx=port address to check for ready
; outpt: CY set if timeout
sbReadReady? proc
        push    ax
        push    cx
        push    dx
        mov     cx, 1000                ; timeout counter
        add     dx, 0eh                 ; read status port
tryAgain:
        in      al, dx
        test    al, BIT7                ; ready status bit set?
        clc                             ; assume it is
        jnz     exit
        loop    tryAgain
        stc
exit:
        pop     dx
        pop     cx
        pop     ax
        ret
sbReadReady? endp

; input: dx=port address to check for ready
; outpt: CY set if timeout
sbWriteReady? proc
        push    ax
        push    cx
        push    dx
        mov     cx, 1000                ; timeout counter
        add     dx, 0ch                 ; write status port
@@:
        in      al, dx
        test    al, BIT7                ; ready status bit clear?
        clc                             ; assume it is
        jz      @f
        loop    @b
        stc
@@:
        pop     dx
        pop     cx
        pop     ax
        ret
sbWriteReady? endp

; input: dx=base address
; outpt: none
sbReset proc
        push    ax
        push    dx
        add     dx, 6                   ; point to reset port
        mov     al, 1                   ; send a 1, then a 0
        out     dx, al
        in	al, 80h			; do input for delay/flush
	mov     al, 0
        out     dx, al
        pop     dx
        pop     ax
        ret
sbReset endp



; input: dx=base address
; outpt: CY set if no SB detected
sbDetect proc
        push    ax
        push    cx
        call    sbReset			; this generates an IRQ
        call    sbReadReady?
        jc      sbDetExit

        mov     cx, 1000                ; timeout count
@@:
        call    sbRead
        cmp     al, 0AAh                ; A-ok signal
        clc
        jz      @f
        loop    @b
        stc
@@:
sbDetExit:
        pop     cx
        pop     ax
        ret
sbDetect endp

; set up IRQs for all possible soundblaster interrupts so we can determine
; which one is being used.
; input: none
; outpt: none, ISRs revectored to our test routine.  Old vectors saved
; in local storage.
snagISRs proc
	push	ax
	push	bx
	push	es
	; save all old interrupt vectors so we can restore them later.

	mov	al, 3
	call	getIRQVector
	mov	cs:[oldISR3Off], bx
	mov	cs:[oldISR3Seg], es

	mov	al, 5
	call	getIRQVector
	mov	cs:[oldISR5Off], bx
	mov	cs:[oldISR5Seg], es

	mov	al, 7
	call	getIRQVector
	mov	cs:[oldISR7Off], bx
	mov	cs:[oldISR7Seg], es


	; set all interrupt vectors to a tiny test routine that sets a flag
	; se we'll know which one fired an interrupt when the SB was reset.
	push	cs
	pop	es

	lea	bx, newISR3 		; test routine
	mov	al, 3
	call	setIRQVector
	lea	bx, newISR5 		; test routine
	mov	al, 5
	call	setIRQVector
	lea	bx, newISR7 		; test routine
	mov	al, 7
	call	setIRQVector
	
	pop	es
	pop	bx
	pop	ax
	ret
snagISRs endp

; restore any vector that we didn't see a signal from.
unsnagISRs proc
	push	ax
	push	bx
	push	es
	test	cs:[isrFlag], BIT3	
	jnz	restoreIRQ5
	
	mov	bx, oldISR3Seg
	mov	es, bx
	mov	bx, oldISR3Off
	mov	al, 3			; IRQ#
	call	setIRQVector		; restore this ISR
	
restoreIRQ5:
	test	cs:[isrFlag], BIT5	
	jnz	restoreIRQ7

	mov	bx, oldISR5Seg
	mov	es, bx
	mov	bx, oldISR5Off
	mov	al, 5		; IRQ#
	call	setIRQVector	; restore this ISR

restoreIRQ7:
	test	cs:[isrFlag], BIT7	
	jnz	exituISR

	mov	bx, oldISR7Seg
	mov	es, bx
	mov	bx, oldISR7Off
	mov	al, 7		; IRQ#
	call	setIRQVector	; restore this ISR

exituISR:		
	in	al, 21h			; get IRQ mask
	mov	ah, cs:[isrFlag]
	not	ah
	and	al, ah			; clear our IRQ
	out	21h, al			; set it in place

	pop	es
	pop	bx
	pop	ax
	ret
unsnagISRs endp

; set the SB IRQ vector to the routine that'll actually do some work.
setSBIRQroutine	proc
	push	ax
	push	bx
	push	es
	push	cs
	pop	es
	lea	bx, sbHandlerroutine
	mov	al, 3
	test	cs:[isrFlag], BIT3
	jnz	setRoutine
	mov	al, 5
	test	cs:[isrFlag], BIT5
	jnz	setRoutine
	mov	al, 7
	test	cs:[isrFlag], BIT7
	jz	noIRQ
setRoutine:
	call	setIRQVector
noIRQ:
	pop	es
	pop	bx
	pop	ax
	ret
setSBIRQroutine	endp



; input: es:bx seg:offset of routine desired
; al=IRQ desired.
setIRQVector proc
	push	ds
	push	dx
	mov	dx, bx
	push	es
	pop	ds

	mov	ah, 25h
	add	al, 8		; vector # is offset by 8 
	int	21h		; replace ISR 
	pop	dx
	pop	ds
	ret
setIRQVector endp

; input: al=IRQ desired.
; outpt: es:bx seg:offset of current routine
getIRQVector proc
	mov	ah, 35h
	add	al, 8		; vector # is offset by 8 
	int	21h		; get ISR 
	ret
getIRQVector endp


oldISR3Seg	dw	?
oldISR3Off	dw	?
oldISR5Seg	dw	?
oldISR5Off	dw	?
oldISR7Seg	dw	?
oldISR7Off	dw	?

isrFlag		db	0
samplePlaying	db	0		; flag so we can wait until finished

newISR3 proc
	push	ax
	or	cs:[isrFlag], BIT3
	mov	al, 20h
	out	20h, al
	pop	ax
	iret
newISR3 endp
newISR5 proc
	push	ax
	or	cs:[isrFlag], BIT5
	mov	al, 20h
	out	20h, al
	pop	ax
	iret
newISR5 endp
newISR7 proc
	push 	ax
	or	cs:[isrFlag], BIT7
	mov	al, 20h
	out	20h, al
	pop	ax
	iret
newISR7 endp



; top level routine to find a soundblaster device.
; input: none
; outpt: CY clear if SB found, dx=base address
sbLocate proc
	test	cs:[flags], noSB	; no sb override switch?
	stc
	jnz	exitSBL

	mov     dx, 200h                ; starting base address
nextAddress:
        add     dx, 10h                 ; next base address
        cmp     dx, 270h
        stc     
        jz      exitSBL
        call    sbDetect                ; see if we can find a SB
        jc      nextAddress



	;
	; mask off IRQs while we futz with vectors for 3,5,7

	in	al, 21h
	mov	ah, al			; save current setting
	or	al, BIT3+BIT5+BIT7	; block 3,5,7

   	call	snagISRs		; capture vectors 5,7,3
	and	al, NOT BIT3+BIT5+BIT7	; enable IRQs 3,5,7
   	out	21h, al
   
	mov	al, 0d3h
	call	sbWrite			; turn off speakers
	
	push	ax
	mov	ax, 0	
	mov	bx, 0
	mov	cx, 50		
	call	playSample		; play a tiny sample to cause IRQ.
	pop	ax

	;
	; hopefully, we've caused an IRQ.
	;
	call	startTime		; wait around til sample finishes
	call	delayTime
	call	startTime
	call	delayTime
	call	startTime
	call	delayTime

	mov	al, 0eh
	call	sbRead			; force a read == end of interrupt

	mov	cs:[samplePlaying], 0	; clear our flag if it's set.
	mov	al, 20h
	out	20h, al

	mov	al, ah			
	out	21h, al			; restore original IRQ mask

   	call	unSnagISRs		; release any unused IRQs
	call	setSBIRQroutine		; set used IRQ to proper routine
	clc
exitSBL:        
	ret
sbLocate endp

; input: al=data to write to data port
;        dx=base address
; outpt: CY set if data port doesn't become ready for receive.
sbWrite proc
        push    dx
        call    sbWriteReady?
        add     dx, 0ch
        out     dx, al
        pop     dx
        ret
sbWrite endp

; input: dx=base address
; outpt: al=8 bits of data from data register
sbRead proc
        push    dx
        call    sbReadReady?
        add     dx, 0ah
        in      al, dx
        pop     dx
        ret
sbRead endp


; input: ax=segment of sample (should be 64k aligned already)
;        bx=offset of sample
;        cx=size of sample (# of samples)
;	 dx=sound blaster base address
playSample proc
	 	push	ax
		push	bx
		push	cx

		dec	cx			; all calculations are 0 based

		mov	al, 0eh
		call	sbRead			; force a read == end of interrupt

		mov	al, 20h
		out	20h, al


		mov	al, 40h			; set sample rate
	      	call	sbWrite
	      
	      	mov	al, cs:[pitch]   	; 256 - (1000000 / 22050)
	      	call	sbWrite
	
		mov	al, 0d1h		; turn on speaker
		call	sbWrite

		call	findPage		; figure out page#



		; check DMA page boundry crossing.
		; it would be very, very bad if this happened.
		push	bx
		add	bx, cx
		jnc	dmaok

		mov	cx, bx			; shorten sample to fix ovrrun
		dec	cx
		
dmaok: 
		pop	bx
		
		
		call	setupDMA		; program the dma controller


		mov	al, 14h			; send size
		call	sbWrite

		mov	al, cl
		call	sbWrite
		mov	al, ch
		call	sbWrite			; start the sample playing
						; IRQ fired when sample is
						; finished
		pop	cx
		pop	bx
		pop	ax
		ret
playSample endp

pitch	db	DEFAULT_PITCH			; 256 - (1000000 / 22050)


; input: ax=segment of sample data to play 
;        bx=offset of sample to play
; outpt: al=page#, bx=offset
findPage proc
	rol	ax, 1		; convert aligned seg# to page
	rol	ax, 1
	rol	ax, 1
	rol	ax, 1
	and	al, 0fh
	ret
findPage endp





; input: al:bx 20bit physical address
;	cx=size of transfer
setupDMA proc
	push	ax
	push	dx
	mov	dx, ax

	mov	al, 5
	out	0ah, al			; mask off channel 1

	mov	al, 0
	out	0ch, al			; clear flip-flop
	
	mov	al, 49h
	out	0bh, al 		; set transfer mode for dma ch 1


	mov	al, bl
	out	02, al			; send offset low byte
	mov	al, bh
	out	02, al			; send high byte 
	
	mov	al, dl
	out	83h, al			; upper page register
	

	mov	al, cl
	out	03, al			; send size lower bits	channel 1
	mov	al, ch
	out	03, al			; upper bits of xfer size  channel 1

	mov	al, 1
	out	0ah, al			; release DMA controller
	pop	dx
	pop	ax
	ret
setupDMA endp


; this is the interrupt service routine that gets called whenever the SB 
; finished playing a sample.  Its job is to simply turn off the speaker.
sbHandlerRoutine proc
	push	ax
	push	dx
	
	mov	dx, cs:[sbBase]
	mov	al, 0d3h
	call	sbWrite			; turn off speaker

	mov	al, 0eh
	call	sbRead			; force a read == end of interrupt

	mov	cs:[samplePlaying], 0	; clear our flag if it's set.
	mov	al, 20h
	out	20h, al
	pop	dx
	pop	ax
	iret
sbHandlerRoutine endp

; input: none
; outpt: none.  soundblaster IRQ cleared and serviced, ISR unhooked.
sbCleanup proc
		push	ax
		push	dx
		mov	dx, cs:[sbBase]
		mov	al, 0d3h    		; turn off speakers
		call	sbWrite

		mov	al, 0eh			; ack any leftover IRQs
		call	sbRead
		mov	al, 20h
		out	20h, al
		
		mov	ah, cs:[isrFlag]	; mask off our IRQ
		in	al, 21h		
		or	al, ah
		out	21h, al

		mov	cs:[isrFlag], 0		; restore all IRQ vectors
		call	unSnagISRs
		pop	dx
		pop	ax
		ret
sbCleanup endp

; this is seriously lame.
; when transferring data, the DMA controller must never ever ever cross
; a 64k boundry.  Normally this wouldn't be a big deal, except where the
; boundries start and stop are constant, and where the program loads data
; into memory is variable, so all of the samples might need to be juggled
; around in memory to align them all on a 64k page boundry.
; 
; the solution I've come up with to fix this is to allocate 192k of memory.
; somewhere in that 192k of memory, we've got to cross a physical 64k boundry.
; figure out where that boundry is, and copy all the samples to it/around it.
; 
moveSamples proc
	push	ax
	push	bx
	push	cx
	push	si
	push	di
	push	es
	push	ds
	mov	ax, 3 * 64 * (1024 / 16)	; request 192k in paragraphs
	call	memAlloc
	jc	outofmemory			; uh oh
	
	mov	cx, ax				; save starting segment
	; figure out where our 1st 64k page crossing is.

  	
  	rol	ax, 1				; * 16 = physical address
  	rol	ax, 1
  	rol	ax, 1
  	rol	ax, 1
  	mov	bl, al				; div by 64k/page
  	and	bl, 0fh				; bl=page
	
	and	ax, 0fff0h 			; ax=offset
	not	ax
	inc	ax
	shr	ax, 1
	shr 	ax, 1
	shr	ax, 1
	shr	ax, 1

	add	ax, cx				; ax=start of next page (seg)
	
	mov	cs:[sampleSeg], ax
	mov	es, ax
	xor	di, di
	mov	ax, soundblasterSeg
	mov	ds, ax
	xor	si, si
	mov	cx, 64 * (1024 / 2)
	rep	movsw

	;
	; copy the next chunk of sample data into next 64k block
	;

	mov	ax, cs:[sampleSeg]
	add	ax, 1000h			; next 64k block

	mov	es, ax
	xor	di, di
	mov	ax, soundBlasterSeg2
	mov	ds, ax
	xor	si, si
	mov	cx, 64 * (1024 / 2)		; not actually this much
	rep	movsw				; but no big deal
	
	clc
outOfMemory:	
	pop	ds
	pop	es
	pop	di
	pop	si
	pop	cx
	pop	bx
	pop	ax
	ret
sampleSeg	dw	?    		;seg ptr for storage for samples

moveSamples endp




;============================================================================



; exit back to DOS.  We are through.
exitProgram:
		cmp	word ptr cs:[sbBase], -1
		jz	noSBRestore

		call	sbCleanup
noSBRestore:

		in	al, 61h
		and	al, NOT BIT0
		out	61h, al			; shut down speaker

		mov     bx, 0                     
                mov     ax, 3
                int     10h

                mov     ax, 4c00h
                int     21h
codeSeg ends

